export function getProfileAvatarStoragePathForUser(
  userId: string | null | undefined,
  avatarUrl: string | null | undefined
): string | null {
  if (!userId || !avatarUrl) {
    return null;
  }

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;

  if (!supabaseUrl) {
    return null;
  }

  try {
    const candidate = new URL(avatarUrl);
    const allowedOrigin = new URL(supabaseUrl).origin;
    const allowedPathPrefix = "/storage/v1/object/public/profile-avatars/";
    const storagePath = decodeURIComponent(candidate.pathname.slice(allowedPathPrefix.length));

    if (
      candidate.origin !== allowedOrigin ||
      !candidate.pathname.startsWith(allowedPathPrefix) ||
      !isProfileAvatarStoragePathForUser(userId, storagePath)
    ) {
      return null;
    }

    return storagePath;
  } catch {
    return null;
  }
}
